    private String homeStatus(){try{android.content.pm.ResolveInfo result=getPackageManager().resolveActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),android.content.pm.PackageManager.MATCH_DEFAULT_ONLY);if(result!=null&&result.activityInfo!=null&&!result.activityInfo.packageName.equals("android"))return result.loadLabel(getPackageManager()).toString()+" · "+result.activityInfo.packageName;}catch(RuntimeException ignored){}return Ui.word(this,"Постоянный выбор не подтверждён","Permanent default not confirmed");}
    private boolean settingHome,checkingHome;private AlertDialog homeProgress;
    private void refreshHomeStatus(){if(checkingHome||isFinishing()||isDestroyed())return;checkingHome=true;new Thread(()->{final String status=homeStatus();runOnUiThread(()->{checkingHome=false;if(isFinishing()||isDestroyed())return;Preference row=findPreference("home");if(row!=null)row.setSummary(status);});},"home-status").start();}
    private void chooseHome(){ActionSheet.show(this,Ui.word(this,"Лаунчер по умолчанию","Default Home app"),new ActionSheet.Item(Ui.word(this,"Выбрать в настройках Android","Choose in Android settings"),"settings",this::chooseHomeInAndroid),new ActionSheet.Item(Ui.word(this,"Сделать True TV Launcher главным (ADB)","Make True TV Launcher the Home app (ADB)"),"check",this::confirmHomeAdb),new ActionSheet.Item(Ui.word(this,"Подключение ADB / TV Access","ADB connection / TV Access"),"access",()->Controls.restricted(this)));}
    private void confirmHomeAdb(){if(settingHome)return;String endpoint=store.text("access_endpoint",store.text("expert_endpoint","127.0.0.1:5555"));new AlertDialog.Builder(this).setTitle(Ui.word(this,"Назначить главным через ADB?","Set default Home through ADB?")).setMessage("True TV Launcher\nADB · "+endpoint+"\n\n"+Ui.word(this,"Кнопка «Домой» будет открывать True TV Launcher. После назначения результат будет прочитан повторно. Отладка должна быть включена и разрешена вами.","The Home button will open True TV Launcher. The assignment will be re-read after the command. Debugging must be enabled and approved by you.")).setNegativeButton(Ui.word(this,"Отмена","Cancel"),null).setPositiveButton(Ui.word(this,"Назначить","Set default"),(d,which)->{settingHome=true;homeProgress=new AlertDialog.Builder(this).setTitle(Ui.word(this,"Назначение главного приложения","Setting default Home")).setMessage(Ui.word(this,"Если появится запрос RSA, разрешите отладку на этом устройстве.","Approve the RSA debugging prompt on this device if it appears.")).setCancelable(false).show();new Thread(()->{String message;try(ExpertBackend backend=new ExpertBackend(this,false,endpoint)){HomeDefaults.assign(backend::shell,ExpertBackend.user(),Build.VERSION.SDK_INT);message=Ui.word(this,"True TV Launcher назначен главным. Выбор подтверждён Android.","True TV Launcher is the default Home app. Android confirmed the assignment.");}catch(HomeDefaults.NotAssigned e){message=Ui.word(this,"Android продолжает выбирать другой главный экран: ","Android still selects another Home app: ")+(e.resolved==null?Ui.word(this,"не определён","not identified"):e.resolved)+(e.priorityOverridesPreference(Build.VERSION.SDK_INT)?Ui.word(this,"\n\nУ него повышенный системный приоритет (","\n\nIt has a higher system priority (")+e.priority+Ui.word(this,"). На Android 7–9 такой приоритет может перекрывать сохранённый выбор. Повторять назначение недостаточно. В разделе системных приложений можно отдельно подтвердить «Всё равно отключить / заморозить» для штатного Home. Эта операция проверяет переключение на True TV и восстанавливает прежний Home при неудаче. Здесь штатный Home не отключался.","). On Android 7–9 this priority can override the saved preference. Repeating the assignment is insufficient. In System apps, you can separately confirm Override: disable / freeze for stock Home. That operation verifies the switch to True TV and restores previous Home state on failure. Stock Home was not disabled here."):Ui.word(this,"\n\nКоманда назначения выполнена, но проверка Android не подтвердила переключение. Настройки прошивки могут ограничивать смену главного экрана.","\n\nThe assignment command completed, but Android did not confirm the change. Firmware settings may restrict Home selection."));}catch(Exception e){message=Ui.word(this,"Назначение не подтверждено: ","Assignment not confirmed: ")+e.getMessage();}final String result=message;runOnUiThread(()->{settingHome=false;if(isFinishing()||isDestroyed())return;homeProgress.dismiss();homeProgress=null;refreshHomeStatus();new AlertDialog.Builder(this).setTitle(Ui.word(this,"Главное приложение","Home app")).setMessage(result).setPositiveButton("OK",null).show();});},"home-adb").start();}).show();}
    protected void onDestroy(){if(volumeTools!=null)volumeTools.close();if(homeProgress!=null)homeProgress.dismiss();super.onDestroy();}
    private void chooseHomeInAndroid(){
        if(Build.VERSION.SDK_INT>=29){try{RoleManager role=(RoleManager)getSystemService(ROLE_SERVICE);if(role!=null&&role.isRoleAvailable(RoleManager.ROLE_HOME)){startActivityForResult(role.createRequestRoleIntent(RoleManager.ROLE_HOME),72);return;}}catch(RuntimeException ignored){}}
        if(Ui.launch(this,new Intent("android.settings.HOME_SETTINGS"))||Ui.launch(this,new Intent("android.settings.MANAGE_DEFAULT_APPS_SETTINGS")))return;
        new AlertDialog.Builder(this).setTitle(Ui.word(this,"Лаунчер по умолчанию","Default Home app")).setMessage(Ui.word(this,"На этой прошивке нет доступного системного экрана выбора лаунчера. Можно назначить True TV Launcher через встроенный ADB-помощник. Подключение и изменение выполняются только после вашего подтверждения.","This firmware exposes no system Home selection screen. You can assign True TV Launcher with the embedded ADB helper. Connection and assignment require your confirmation.")).setNegativeButton(Ui.word(this,"Отмена","Cancel"),null).setPositiveButton(Ui.word(this,"Назначить через ADB…","Set through ADB…"),(d,which)->confirmHomeAdb()).show();
    }
    private PreferenceCategory section(PreferenceScreen root,String ru,String en){PreferenceCategory c=new PreferenceCategory(this){protected android.view.View onCreateView(android.view.ViewGroup parent){LinearLayout box=new LinearLayout(SettingsActivity.this);box.setOrientation(1);box.setPadding(Ui.dp(SettingsActivity.this,16),Ui.dp(SettingsActivity.this,12),Ui.dp(SettingsActivity.this,16),Ui.dp(SettingsActivity.this,6));android.view.View rule=new android.view.View(SettingsActivity.this);rule.setBackgroundColor(Ui.border(SettingsActivity.this));box.addView(rule,new LinearLayout.LayoutParams(-1,Ui.dp(SettingsActivity.this,1)));TextView title=Ui.label(SettingsActivity.this,getTitle(),15);title.setId(android.R.id.title);title.setTextColor(Ui.accent(SettingsActivity.this));title.setPadding(0,Ui.dp(SettingsActivity.this,10),0,0);box.addView(title);return box;}};c.setTitle(Ui.word(this,ru,en));root.addPreference(c);return c;}
    private CheckBoxPreference toggle(PreferenceCategory parent,String key,String ru,String en,String summaryRu,String summaryEn,boolean fallback){CheckBoxPreference p=new CheckBoxPreference(this);p.setKey(key);p.setTitle(Ui.word(this,ru,en));p.setSummary(Ui.word(this,summaryRu,summaryEn));p.setDefaultValue(Defaults.flag(key,fallback));p.setOnPreferenceChangeListener((pref,value)->{if(SettingsStore.layoutKey(key)&&Boolean.TRUE.equals(value)!=store.flag(key,fallback))store.layoutChanged();return true;});parent.addPreference(p);return p;}
    private void list(PreferenceCategory parent,String key,String ru,String en,String[] entries,String[] values,String fallback){ListPreference p=new SheetListPreference(this);p.setKey(key);p.setTitle(Ui.word(this,ru,en));p.setEntries(entries);p.setEntryValues(values);p.setDefaultValue(Defaults.text(key,fallback));parent.addPreference(p);p.setSummary(p.getEntry());p.setOnPreferenceChangeListener((pref,value)->{int index=p.findIndexOfValue(String.valueOf(value));if(index>=0)p.setSummary(p.getEntries()[index]);if(SettingsStore.layoutKey(key)&&!String.valueOf(value).equals(store.text(key,fallback)))store.layoutChanged();return true;});}
    private Preference action(PreferenceCategory parent,String key,String ru,String en,Runnable run){Preference p=new Preference(this);p.setKey(key);p.setTitle(Ui.word(this,ru,en));p.setOnPreferenceClickListener(value->{run.run();return true;});parent.addPreference(p);return p;}
    protected void onResume(){super.onResume();if(!Ui.appearance(this).equals(appearance)){recreate();return;}Ui.bars(this);if(store.flag("running_pending",false)){boolean granted=StatusWatch.usageAllowed(this);store.data.edit().putBoolean("running",granted).putBoolean("running_pending",false).apply();running.setChecked(granted);}refreshAccess();Controls.observe(this);refreshHomeStatus();}
    public void refreshAccess(){if(access!=null)access.setSummary(Ui.word(this,Controls.ready(this)?"Включена":"Не включена: серые пункты откроют страницу доступа",Controls.ready(this)?"Enabled":"Off: grey actions open Accessibility settings"));}
    protected void onPause(){Controls.unobserve(this);super.onPause();}
